begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values
 ('b1000000-0000-4000-8000-000000000001','invite-owner@example.invalid'),
 ('b1000000-0000-4000-8000-000000000002','invite-other@example.invalid');
create temporary table commands(name text primary key,result jsonb);
grant all on commands to authenticated;
set local role authenticated;
set local request.jwt.claim.sub='b1000000-0000-4000-8000-000000000001';
insert into commands values('loan',public.create_loan('LENDER',1000,'VND','2026-09-01','2026-10-01',null,null,'b2000000-0000-4000-8000-000000000001'));
set local request.jwt.claim.sub='b1000000-0000-4000-8000-000000000002';
select throws_ok($$select public.manage_loan_invite((select (result->>'loan_id')::uuid from commands where name='loan'),'rotate','b2000000-0000-4000-8000-000000000002')$$,'42501','LOAN_ACCESS_DENIED','Non-owner cannot replace an invitation');
set local request.jwt.claim.sub='b1000000-0000-4000-8000-000000000001';
insert into commands values('rotated',public.manage_loan_invite((select (result->>'loan_id')::uuid from commands where name='loan'),'rotate','b2000000-0000-4000-8000-000000000003'));
select isnt((select result->>'invite_token' from commands where name='rotated'),(select result->>'invite_token' from commands where name='loan'),'Replacement uses a different random token');
select is(public.manage_loan_invite((select (result->>'loan_id')::uuid from commands where name='loan'),'rotate','b2000000-0000-4000-8000-000000000003'),(select result from commands where name='rotated'),'Retry returns the same live replacement');
select throws_ok($$select public.manage_loan_invite((select (result->>'loan_id')::uuid from commands where name='loan'),'revoke','b2000000-0000-4000-8000-000000000003')$$,'P0001','IDEMPOTENCY_PAYLOAD_MISMATCH','Key cannot change rotation into revocation');
select is(public.create_loan('LENDER',1000,'VND','2026-09-01','2026-10-01',null,null,'b2000000-0000-4000-8000-000000000001')->>'invite_token',null::text,'Original creation receipt hides the revoked token');
set local request.jwt.claim.sub='b1000000-0000-4000-8000-000000000002';
select throws_ok($$select public.accept_loan_invite((select result->>'invite_token' from commands where name='loan'),'b2000000-0000-4000-8000-000000000004')$$,'P0001','INVITE_REVOKED','Old link cannot join after replacement');
select lives_ok($$select public.get_loan_invite_preview((select result->>'invite_token' from commands where name='rotated'))$$,'Replacement preview works for a signed-in holder');
set local request.jwt.claim.sub='b1000000-0000-4000-8000-000000000001';
select lives_ok($$select public.manage_loan_invite((select (result->>'loan_id')::uuid from commands where name='loan'),'revoke','b2000000-0000-4000-8000-000000000005')$$,'Owner can revoke without replacement');
select is(public.manage_loan_invite((select (result->>'loan_id')::uuid from commands where name='loan'),'rotate','b2000000-0000-4000-8000-000000000003')->>'invite_token',null::text,'Retry cannot resurrect a revoked replacement');
set local request.jwt.claim.sub='b1000000-0000-4000-8000-000000000002';
select throws_ok($$select public.accept_loan_invite((select result->>'invite_token' from commands where name='rotated'),'b2000000-0000-4000-8000-000000000006')$$,'P0001','INVITE_REVOKED','Revoked replacement cannot join');
set local request.jwt.claim.sub='b1000000-0000-4000-8000-000000000001';
insert into commands values('fresh',public.manage_loan_invite((select (result->>'loan_id')::uuid from commands where name='loan'),'rotate','b2000000-0000-4000-8000-000000000007'));
select is((select count(*) from public.loan_events where loan_id=(select (result->>'loan_id')::uuid from commands where name='loan') and event_type='INVITE_REVOKED'),2::bigint,'Audit records replacement and owner revocation once each');
set local request.jwt.claim.sub='b1000000-0000-4000-8000-000000000002';
select lives_ok($$select public.accept_loan_invite((select result->>'invite_token' from commands where name='fresh'),'b2000000-0000-4000-8000-000000000008')$$,'Fresh link joins after revocation');
set local request.jwt.claim.sub='b1000000-0000-4000-8000-000000000001';
select throws_ok($$select public.manage_loan_invite((select (result->>'loan_id')::uuid from commands where name='loan'),'rotate','b2000000-0000-4000-8000-000000000009')$$,'P0001','LOAN_NOT_PENDING','No new invitation after membership accepted');
select is(public.manage_loan_invite((select (result->>'loan_id')::uuid from commands where name='loan'),'rotate','b2000000-0000-4000-8000-000000000007')->>'invite_token',null::text,'Used token is not returned from rotation receipt');
reset role;
select ok(not has_function_privilege('anon','public.manage_loan_invite(uuid,text,uuid)','EXECUTE'),'Anonymous caller cannot manage invitations');
select * from finish();
rollback;
